#!/usr/bin/env bash
# Open Grafana (kube-prometheus-stack, installed by Scripts/deploy.sh) on
# http://localhost:3001 through a kubectl port-forward, after printing its admin
# credentials (random password generated by the chart). Ctrl-C closes it.
#
# Grafana has no public address: this port-forward is the only way in.
#
# Usage: Scripts/grafana.sh
#
# Environment:
#   GRAFANA_PORT  local port (default 3001; 3000 is often taken by a local web app)
#   KUBE_CONTEXT  kubectl context of the cluster (default cloud-design)
set -euo pipefail

PORT="${GRAFANA_PORT:-3001}"
KUBE_CONTEXT="${KUBE_CONTEXT:-cloud-design}"

if [[ "${1:-}" == "-h" || "${1:-}" == "--help" ]]; then
  sed -n '2,/^set -euo/p' "$0" | sed '$d' | cut -c3-
  exit 0
fi

secret() {
  kubectl --context "$KUBE_CONTEXT" -n monitoring get secret monitoring-grafana \
    -o "jsonpath={.data.$1}" | base64 -d
}

echo "Grafana: http://localhost:$PORT"
echo "  user:     $(secret admin-user)"
echo "  password: $(secret admin-password)"
echo "Dashboards: Kubernetes / Compute Resources / Namespace (Pods), namespace cloud-design"
exec kubectl --context "$KUBE_CONTEXT" -n monitoring port-forward service/monitoring-grafana "$PORT:80"
